type Cache struct {
	mu    sync.Mutex
	items map[string]string
}

func (c *Cache) Get(k string) string {
	c.mu.Lock()
	v := c.items[k]
	c.mu.Unlock()
	return v
}

func (c *Cache) Set(k, v string) {
	c.mu.Lock()
	if c.items == nil {
		c.items = map[string]string{}
	}
	c.items[k] = v
	c.mu.Unlock()
}

func (c *Cache) Len() int {
	return len(c.items)
}
