```python
class Cart:
    def __init__(self, items):
        self.items = items
        self.discounts = []

    def apply(self, discount):
        self.discounts.append(discount)

    def _line_totals(self):
        for item in self.items:
            price = Decimal(item.price)
            for d in self.discounts:
                price = d.apply(price, share=item.price / self.subtotal())
            yield price

    def subtotal(self):
        return sum(i.price for i in self.items)

    def total(self):
        return self._round(sum(self._line_totals()))

    def _round(self, value):
        return value.quantize(Decimal('0.01'), rounding=ROUND_DOWN)

class Fixed:
    def __init__(self, amount):
        self.amount = amount

    def apply(self, price, share):
        return price - Decimal(self.amount * share)
```
The fix must not change rounding for single discounts, which other tests depend on.

