```go
type Registry struct {
	mu       sync.RWMutex
	sessions map[string]*Session
}

func (r *Registry) Track(id string) *Session {
	r.mu.RLock()
	s, ok := r.sessions[id]
	r.mu.RUnlock()
	if !ok {
		s = &Session{ID: id, Seen: time.Now()}
		r.sessions[id] = s
	}
	s.Seen = time.Now()
	return s
}

func (r *Registry) Expire() {
	r.mu.Lock()
	defer r.mu.Unlock()
	for id, s := range r.sessions {
		if time.Since(s.Seen) > time.Hour {
			delete(r.sessions, id)
		}
	}
}
```

